// String Template Engine
// Mustache/Handlebars-style templating

var template = input.get("template");
var dataInput = input.get("data");

if (!template) {
    log.error("Template is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Template is required");
    output.set("Result", "");
    tags.trigger("error");
} else {
    try {
        // Parse data input
        var data = {};
        if (dataInput && dataInput.trim()) {
            data = json.parse(dataInput);
        }

        // Get nested property value
        function getValue(obj, path) {
            if (!path) return obj;
            var parts = path.split('.');
            var current = obj;
            for (var i = 0; i < parts.length; i++) {
                if (current === null || current === undefined) return undefined;
                var part = parts[i];
                // Handle array index notation: items[0]
                var match = part.match(/^(.+)\[(\d+)\]$/);
                if (match) {
                    current = current[match[1]];
                    if (Array.isArray(current)) {
                        current = current[parseInt(match[2])];
                    } else {
                        return undefined;
                    }
                } else {
                    current = current[part];
                }
            }
            return current;
        }

        // Check if value is truthy
        function isTruthy(val) {
            if (val === null || val === undefined || val === false || val === 0 || val === "") return false;
            if (Array.isArray(val) && val.length === 0) return false;
            return true;
        }

        // Process template
        function processTemplate(tpl, ctx) {
            var result = tpl;

            // Process {{#each array}}...{{/each}} blocks
            var eachRegex = /\{\{#each\s+([^}]+)\}\}([\s\S]*?)\{\{\/(each|\1)\}\}/g;
            var eachMatch;
            while ((eachMatch = eachRegex.exec(result)) !== null) {
                var arrayPath = eachMatch[1].trim();
                var innerTemplate = eachMatch[2];
                var fullMatch = eachMatch[0];

                var arr = getValue(ctx, arrayPath);
                var replacement = "";

                if (Array.isArray(arr)) {
                    for (var i = 0; i < arr.length; i++) {
                        var itemCtx = {};
                        // Copy parent context
                        var ctxKeys = Object.keys(ctx);
                        for (var k = 0; k < ctxKeys.length; k++) {
                            itemCtx[ctxKeys[k]] = ctx[ctxKeys[k]];
                        }
                        // Add loop-specific variables
                        itemCtx["this"] = arr[i];
                        itemCtx["@index"] = i;
                        itemCtx["@first"] = i === 0;
                        itemCtx["@last"] = i === arr.length - 1;

                        // If item is an object, merge its properties
                        if (typeof arr[i] === "object" && arr[i] !== null) {
                            var itemKeys = Object.keys(arr[i]);
                            for (var j = 0; j < itemKeys.length; j++) {
                                itemCtx[itemKeys[j]] = arr[i][itemKeys[j]];
                            }
                        }

                        replacement += processTemplate(innerTemplate, itemCtx);
                    }
                }

                result = result.replace(fullMatch, replacement);
                eachRegex.lastIndex = 0; // Reset regex for next iteration
            }

            // Process {{#if condition}}...{{else}}...{{/if}} blocks
            var ifElseRegex = /\{\{#if\s+([^}]+)\}\}([\s\S]*?)\{\{else\}\}([\s\S]*?)\{\{\/(if|\1)\}\}/g;
            var ifElseMatch;
            while ((ifElseMatch = ifElseRegex.exec(result)) !== null) {
                var condPath = ifElseMatch[1].trim();
                var trueBlock = ifElseMatch[2];
                var falseBlock = ifElseMatch[3];
                var ifFullMatch = ifElseMatch[0];

                var condValue = getValue(ctx, condPath);
                var ifReplacement = isTruthy(condValue) ? processTemplate(trueBlock, ctx) : processTemplate(falseBlock, ctx);

                result = result.replace(ifFullMatch, ifReplacement);
                ifElseRegex.lastIndex = 0;
            }

            // Process {{#if condition}}...{{/if}} blocks (without else)
            var ifRegex = /\{\{#if\s+([^}]+)\}\}([\s\S]*?)\{\{\/(if|\1)\}\}/g;
            var ifMatch;
            while ((ifMatch = ifRegex.exec(result)) !== null) {
                var condPath2 = ifMatch[1].trim();
                var content = ifMatch[2];
                var ifFullMatch2 = ifMatch[0];

                var condValue2 = getValue(ctx, condPath2);
                var ifReplacement2 = isTruthy(condValue2) ? processTemplate(content, ctx) : "";

                result = result.replace(ifFullMatch2, ifReplacement2);
                ifRegex.lastIndex = 0;
            }

            // Process {{#unless condition}}...{{/unless}} blocks
            var unlessRegex = /\{\{#unless\s+([^}]+)\}\}([\s\S]*?)\{\{\/(unless|\1)\}\}/g;
            var unlessMatch;
            while ((unlessMatch = unlessRegex.exec(result)) !== null) {
                var unlessPath = unlessMatch[1].trim();
                var unlessContent = unlessMatch[2];
                var unlessFullMatch = unlessMatch[0];

                var unlessValue = getValue(ctx, unlessPath);
                var unlessReplacement = !isTruthy(unlessValue) ? processTemplate(unlessContent, ctx) : "";

                result = result.replace(unlessFullMatch, unlessReplacement);
                unlessRegex.lastIndex = 0;
            }

            // Process {{variable}} interpolations
            var varRegex = /\{\{([^#/}][^}]*)\}\}/g;
            result = result.replace(varRegex, function(match, varPath) {
                var val = getValue(ctx, varPath.trim());
                if (val === undefined || val === null) return "";
                if (typeof val === "object") return json.stringify(val);
                return String(val);
            });

            return result;
        }

        var resultText = processTemplate(template, data);

        output.set("Result", resultText);
        output.set("HasErrors", false);
        output.set("ErrorMessage", "");
        log.info("Template processed: " + resultText.length + " chars output");
        tags.trigger("success");

    } catch (ex) {
        log.error("Template processing failed: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", ex.message);
        output.set("Result", "");
        tags.trigger("error");
    }
}
